function DataTable({columns,rows,empty="No records to show.",numbered=false,className,pagination}:{columns:{label:string;render:(row:Row)=>React.ReactNode}[];rows:Row[];empty?:string;numbered?:boolean;className?:string;pagination?:{page:number;pageSize:number;onPageChange:(page:number)=>void;onPageSizeChange:(pageSize:number)=>void;itemLabel?:string}}){
 const totalPages=pagination?Math.max(1,Math.ceil(rows.length/pagination.pageSize)):1;
 const currentPage=pagination?Math.min(pagination.page,totalPages):1;
 const pageOffset=pagination?(currentPage-1)*pagination.pageSize:0;
 const visibleRows=pagination?rows.slice(pageOffset,pageOffset+pagination.pageSize):rows;
 useEffect(()=>{if(pagination&&pagination.page>totalPages)pagination.onPageChange(1);},[pagination,totalPages]);
 return <><Table className={className}><TableHeader><TableRow>{numbered&&<TableHead key="row-number">#</TableHead>}{columns.map((c,i)=><TableHead key={c.label||"col-"+i}>{c.label||<span className="sr-only">Actions</span>}</TableHead>)}</TableRow></TableHeader><TableBody>{visibleRows.map((r,rowIndex)=><TableRow key={r.id}>{numbered&&<TableCell key="row-number">{pageOffset+rowIndex+1}</TableCell>}{columns.map((c,i)=><TableCell key={c.label||"col-"+i} data-label={c.label}>{c.render(r)}</TableCell>)}</TableRow>)}</TableBody></Table>{!visibleRows.length&&<div className="empty"><FolderOpen size={28}/>{empty}</div>}{pagination&&<DtrPagination page={currentPage} pageSize={pagination.pageSize} totalItems={rows.length} itemLabel={pagination.itemLabel} onPageChange={pagination.onPageChange} onPageSizeChange={pagination.onPageSizeChange}/>}</>;
}
function Panel({title,description,action,children,className}:{title:string;description?:string;action?:React.ReactNode;children:React.ReactNode;className?:string}){return <section className={`panel ${className??''}`}><div className="panel-head"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div>{children}</section>;}
function CompanyDirectoryTab({companies,reviews,role,onViewCompany,onModerateReview}:{companies:Row[];reviews:Row[];role:string;onViewCompany:(company:Row)=>void;onModerateReview:(review:Row)=>void}){
 const pendingReviews=reviews.filter(review=>review.status==='PENDING');
 return <>
  {companies.length?<div className="cards-grid">{companies.map(company=>{
   const publishedReviews=reviews.filter(review=>review.companyId===company.id&&review.status==='APPROVED');
   const rating=publishedReviews.length?publishedReviews.reduce((total,review)=>total+n(review,'rating'),0)/publishedReviews.length:null;
   return <section className="item-card" key={company.id}>
    <div className="item-card-top"><span className="company-symbol">{s(company,'name')[0]}</span><Badge value={company.status==='APPROVED'?'VERIFIED':'PENDING'}/></div>
    <div><h3>{s(company,'name')}</h3><p>{s(company,'industry')} · {s(company,'location')}</p></div>
    <p>{s(company,'description')}</p>
    <div className="item-card-bottom"><Star size={15} fill="#c5aa75" color="#c5aa75"/><span className="small muted">{rating?rating.toFixed(1)+' / 5':'No published reviews'}{publishedReviews.length?' · '+publishedReviews.length+' sample review':''}</span><button className="textbutton" style={{marginLeft:'auto'}} onClick={()=>onViewCompany(company)}>View company</button></div>
   </section>;
  })}</div>:<div className="empty"><Building2 size={28}/>No companies found matching your search.</div>}
  {role==='COORDINATOR'&&pendingReviews.length>0&&<Panel title="Reviews awaiting moderation"><DataTable rows={pendingReviews} columns={[{label:'STUDENT',render:review=>s(review,'studentName')},{label:'REVIEW',render:review=>s(review,'body')},{label:'',render:review=><button className="textbutton" onClick={()=>onModerateReview(review)}>Moderate</button>} ]}/></Panel>}
 </>;
}
