 useEffect(()=>{const context=(document as unknown as {modelContext?:{registerTool:(tool:unknown,options?:{signal:AbortSignal})=>unknown}}).modelContext;if(!context||!data)return;const lifecycle=new AbortController();context.registerTool({name:'practisync_open_section',description:'Navigate to a PractiSync workspace section without submitting data.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['overview','attendance','documents','required-documents','competencies','jobs','announcements','directory','portfolio','profile','settings']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input:unknown){const section=(input as {section?:unknown})?.section;if(typeof section!=='string'||!['overview','attendance','documents','required-documents','competencies','jobs','announcements','directory','portfolio','profile','settings'].includes(section))throw new Error('Invalid section.');if(section==='required-documents'&&data.user.role!=='SUPER_ADMIN')throw new Error('Required OJT documents are managed by Super Admin.');navigate(section);return {section};}},{signal:lifecycle.signal});return()=>lifecycle.abort();},[data,navigate]);
